104	  // The builder is instructed to rewrite the title/description/OG tags below
105	  // for every new site (see lib/agent.ts). If it doesn't, lib/site-seo.ts
106	  // substitutes the project name at serve time — a published site must never
107	  // show "Kodely Site" in a browser tab, a search result, or a link preview.
108	  //
109	  // This file is also the TEMPLATE FOR EVERY OTHER PAGE. A second page is a
110	  // copy of it with its own <head> and its own data-page: that is what makes
111	  // /about a real, separately-indexable document rather than a state of the
112	  // home page. `data-page` is how the document tells the bundle which page it
113	  // is — never sniffed from location.pathname, which differs between
114	  // <slug>.kodely.site/about, /api/site/<slug>/about on staging, and
115	  // about:srcdoc in the editor preview.
116	  "index.html": `<!doctype html>
117	<html lang="en">
118	  <head>
119	    <meta charset="UTF-8" />
120	    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
121	    <title>Kodely Site</title>
122	    <meta name="description" content="" />
123	    <meta property="og:title" content="" />
124	    <meta property="og:description" content="" />
125	    <meta property="og:type" content="website" />
126	    <meta name="twitter:card" content="summary_large_image" />
127	  </head>
128	  <body>
129	    <div id="root" data-page="/"></div>
130	    <script type="module" src="/src/main.tsx"></script>
131	  </body>
132	</html>
133	`,
