57	import {
58	  getLook,
59	  LOOK_DIRECTIONS,
60	  templatesForCategory,
61	  WIZARD_CATEGORIES,
62	  type LookDirection,
63	  type WizardCategory,
64	} from "@/lib/wizard";
65	
66	import {
67	  assembleInlineBrief,
68	  CREATE_CREDIT_ESTIMATE,
69	  EMPTY_INLINE_ANSWERS,
70	  hasInlineAnswers,
71	  LIMITS,
72	  TONES,
73	  type DensityFeel,
74	  type InlineAnswers,
75	  type TypeFeel,
76	} from "./inline-brief";
77	import { LOGO_ACCEPT, prepareLogo } from "./inline-logo";
78	
79	/**
80	 * The inline build wizard — five stages, opened in place on the Create Website
81	 * page rather than by navigating off to /wizard.
82	 *
83	 * ## What it is, and what it is not
84	 *
85	 * It is a way to WRITE A PROMPT, and it hands that prompt back through
86	 * `onComplete`. It never starts a build, never calls a model and never touches
87	 * the network: every stage is local string work over lib/wizard.ts and
88	 * lib/features.ts, so it behaves identically on a bad connection and costs
89	 * nothing to open. The public /wizard is untouched and still works exactly as
90	 * it did — this SHARES its assembly (`assemblePrompt`) rather than forking it,
91	 * so a change to the starter briefs reaches both.
92	 *
93	 * ## Every stage is skippable, and going back never costs an answer
94	 *
95	 * Stage 1 carries a "Skip to the prompt" that jumps straight to review with
96	 * whatever has been answered so far, and every stage before review has a "Skip
97	 * this step". Answers live in one state object for the whole session, so Back
98	 * and Next are lossless in both directions — including across a close and
99	 * reopen, which resumes exactly where the customer left off rather than
100	 * discarding their work for tidiness.
101	 *
102	 * ## Honesty is the feature
103	 *
104	 * Stage 4 offers only what a finished, published Kodely site genuinely does
105	 * (see the long note at the top of lib/features.ts). Each catch sits next to
106	 * its own toggle rather than in small print, and the things we cannot build are
107	 * named on the same screen with the real reason and a real alternative — never
108	 * as a greyed-out row implying that paying would unlock them. The credit figure
109	 * on stage 5 is a RANGE, because a build is an agent loop of unknown length and
110	 * a single number would be a quote nobody can honour.
111	 */
112	
113	export type InlineWizardResult = {
114	  /** The finished, editable build prompt. */
115	  prompt: string;
116	  logoDataUrl?: string;
117	  palette?: string[];
118	};
119	
120	const STAGES = [
121	  { id: "describe", label: "Describe it" },
122	  { id: "details", label: "Site details" },
123	  { id: "style", label: "Style & layout" },
124	  { id: "features", label: "Features" },
125	  { id: "review", label: "Review & build" },
126	] as const;
127	
128	const LAST = STAGES.length - 1;
129	
130	/**
131	 * The one focus ring, on a control whose real input is visually hidden.
132	 *
133	 * `k-focus` matches an element's OWN :focus-visible, which never fires on a
134	 * <label> wrapping an sr-only radio — the input is what receives focus. This is
135	 * the same `has-[:focus-visible]` treatment components/ui/Segmented.tsx uses,
136	 * with the same values as the `.k-focus` rule in app/globals.css, so the
137	 * product still has exactly one focus ring.
138	 */
139	const WRAPPED_FOCUS =
140	  "has-[:focus-visible]:outline has-[:focus-visible]:outline-2 " +
141	  "has-[:focus-visible]:outline-offset-2 has-[:focus-visible]:outline-[var(--brand-ring)]";
142	
143	export function InlineWizard({
144	  open,
145	  onClose,
146	  onComplete,
147	}: {
148	  open: boolean;
149	  onClose: () => void;
150	  onComplete: (result: InlineWizardResult) => void;
151	}): React.ReactNode {
152	  const [stage, setStage] = useState(0);
153	  const [answers, setAnswers] = useState<InlineAnswers>(EMPTY_INLINE_ANSWERS);
154	  /** Non-null once the review textarea has been touched. Revert throws it away. */
155	  const [edited, setEdited] = useState<string | null>(null);
156	  const [logoError, setLogoError] = useState<string | null>(null);
157	  const headingRef = useRef<HTMLHeadingElement>(null);
158	
159	  const assembled = useMemo(() => assembleInlineBrief(answers), [answers]);
160	  const promptText = edited ?? assembled;
161	
162	  // Swapping the whole panel leaves a keyboard or screen-reader user focused on
163	  // a control that no longer means what it did. The sr-only status region below
164	  // announces the change; this puts the caret where the new content starts.
165	  // Modal is a child, and child effects commit first, so the dialog is already
166	  // open and focusable by the time this runs.
167	  useEffect(() => {
168	    if (!open) return;
169	    headingRef.current?.focus();
170	  }, [open, stage]);
171	
172	  /**
173	   * Any change to an answer invalidates a hand-edit of the assembled prompt.
174	   * Silently keeping the old text would mean the palette they just changed
175	   * never reaching the build; dropping the edit is the honest failure, and the
176	   * review stage is one click away. Same contract as the public wizard.
177	   */
178	  function update(patch: Partial<InlineAnswers>) {
179	    setAnswers((prev) => ({ ...prev, ...patch }));
180	    setEdited(null);
181	  }
182	
183	  function pickCategory(category: WizardCategory) {
184	    const first = templatesForCategory(category)[0];
185	    update({ category, templateId: first?.id ?? null });
186	  }
187	
188	  function toggleFeature(id: string) {
189	    setAnswers((prev) => ({
190	      ...prev,
191	      featureIds: prev.featureIds.includes(id)
192	        ? prev.featureIds.filter((f) => f !== id)
193	        : [...prev.featureIds, id],
194	    }));
195	    setEdited(null);
196	  }
197	
198	  /**
199	   * Skip.
200	   *
201	   * On the two CHOICE stages it means "no preference", so it clears what that
202	   * stage contributed — a look half-picked and then skipped past is not what
203	   * the customer asked for. On the two TEXT stages every field is already
204	   * optional, so skipping is the same as Next and nothing typed is thrown away;
205	   * the control is still there because being able to move on without reading
206	   * the fields is the point. Same reasoning the public wizard records for its
207	   * own first step.
208	   */
209	  function skip() {
210	    if (stage === 2) {
211	      update({ lookId: null, tone: null, typeFeel: "look", density: "look", logo: null });
212	      setLogoError(null);
213	    }
214	    if (stage === 3) update({ featureIds: [] });
215	    setStage((s) => Math.min(s + 1, LAST));
216	  }
217	
218	  function finish() {
219	    const text = promptText.trim();
220	    if (!text) return;
221	    const look = answers.lookId ? getLook(answers.lookId) : undefined;
222	    onComplete({
223	      prompt: text,
224	      ...(answers.logo ? { logoDataUrl: answers.logo.dataUrl } : {}),
225	      ...(look ? { palette: look.gradient.colors } : {}),
226	    });
227	  }
228	
229	  const matches = templatesForCategory(answers.category);
230	  const chosenFeatures = selectedFeatures(answers.featureIds);
231	
232	  return (
233	    <Modal
234	      open={open}
235	      onClose={onClose}
236	      size="lg"
237	      title="Build your website"
238	      description="Five short stages. Every one is optional, and you read and edit the finished prompt before anything is built."
239	      footer={
240	        <>
241	          <div className="mr-auto flex items-center gap-1">
242	            {stage > 0 && (
243	              <Button
244	                variant="ghost"
245	                size="sm"
246	                icon={<ArrowLeft size={14} />}
247	                onClick={() => setStage((s) => Math.max(s - 1, 0))}
248	              >
249	                Back
250	              </Button>
251	            )}
252	            {/* Only on the first stage. Anywhere later "Skip this step" already
253	                walks forward, and a second control saying almost the same thing
254	                would just be two ways to guess. */}
255	            {stage === 0 && (
256	              <Button variant="ghost" size="sm" onClick={() => setStage(LAST)}>
257	                Skip to the prompt
258	              </Button>
259	            )}
260	          </div>
261	
262	          {stage < LAST ? (
263	            <>
264	              <Button variant="ghost" size="sm" onClick={skip}>
265	                Skip this step
266	              </Button>
267	              <Button
268	                variant="primary"
269	                size="sm"
270	                iconRight={<ArrowRight size={14} />}
271	                onClick={() => setStage((s) => Math.min(s + 1, LAST))}
272	              >
273	                Next
274	              </Button>
275	            </>
276	          ) : (
277	            <Button
278	              variant="primary"
279	              size="sm"
280	              icon={<Sparkles size={14} />}
281	              disabled={!promptText.trim()}
282	              onClick={finish}
283	            >
284	              Use this prompt
285	            </Button>
286	          )}
287	        </>
288	      }
289	    >
290	      {/* Stage changes are a whole-panel swap with no navigation behind them,
291	          so they are invisible to assistive tech unless announced. */}
292	      <p role="status" className="sr-only">
293	        {`Stage ${stage + 1} of ${STAGES.length}: ${STAGES[stage].label}.`}
294	      </p>
295	
296	      {/* Bounded to the space actually left inside the dialog, not to a guess
297	          at the viewport in isolation. The native <dialog> in Modal.tsx has no
298	          height or overflow of its own, so it falls back to the browser's UA
299	          default (`overflow: auto`, `max-height: calc(100% - Npx)` of the
300	          viewport) — if this whole block were allowed to grow past what that
301	          leaves once Modal's own title, description and footer are accounted
302	          for, the DIALOG ITSELF starts scrolling as a second, independent
303	          scroll container around the one below, wrapping the header and
304	          footer with it (verified: at a 1280×600 viewport on the Features
305	          stage, `dialog.scrollHeight` exceeds `dialog.clientHeight` at the same
306	          time the inner region overflows). Capping this outer flex column
307	          well under 100dvh and letting only the stage content flex is what
308	          keeps the dialog itself at `fit-content` and guarantees there is
309	          exactly one scrollbar.
310	
311	          `relative` is load-bearing for a second, less visible reason: every
312	          sr-only radio in these stages (category chips, look cards, tone
313	          chips) is `position: absolute` with no positioned ancestor of its
314	          own. Without a positioned ancestor HERE, its containing block is the
315	          native <dialog> itself — `dialog:modal` is `position: fixed` in the
316	          UA stylesheet — so its off-screen "hypothetical static position"
317	          (wherever it would have sat in the unclipped flow, which can be
318	          hundreds of pixels below the fold on the longer stages) inflates the
319	          DIALOG's own scrollable-overflow area straight through both
320	          `overflow-hidden` here and the `overflow-y-auto` below, independent
321	          of the max-height fix above (verified: even after that fix,
322	          `dialog.scrollTop` could still be driven to 71px on the shortest
323	          stage, dragging the header off the top of the card). Anchoring the
324	          containing block here keeps it local, where `overflow-hidden`
325	          actually clips it. */}
326	      <div className="relative flex max-h-[max(8rem,calc(100dvh-18rem))] flex-col overflow-hidden">
327	        <div className="flex shrink-0 items-center justify-between gap-3 border-b border-hair pb-3">
328	          <Logo markSize={20} className="text-[0.9375rem]" />
329	          <Badge tone="brand">
330	            Stage <span className="k-num">{stage + 1}</span> of{" "}
331	            <span className="k-num">{STAGES.length}</span>
332	          </Badge>
333	        </div>
334	
335	        {/* The rail is the visual half of the indicator only — the sr-only status
336	            line above is what a screen reader hears. Hidden from the tree rather
337	            than left to compete with it: AIProgress carries its own aria-live,
338	            and two announcements for one change is one too many. */}
339	        <div aria-hidden className="mt-3.5 shrink-0">
340	          <AIProgress
341	            steps={stepsAt(STAGES, stage)}
342	            className="sm:flex-row sm:flex-wrap sm:gap-x-4 sm:gap-y-1.5"
343	          />
344	        </div>
345	
346	        {/* The ONE scroll region. `min-h-0` is load-bearing on a flex child —
347	            without it a flex item refuses to shrink below its content's natural
348	            height, which is exactly the bug this whole wrapper exists to avoid. */}
349	        <div className="mt-4 min-h-0 flex-1 overflow-y-auto pr-1">
350	          {stage === 0 && (
351	            <DescribeStage
352	              headingRef={headingRef}
353	              answers={answers}
354	              matches={matches}
355	              onPickCategory={pickCategory}
356	              onUpdate={update}
357	            />
358	          )}
359	          {stage === 1 && (
360	            <DetailsStage headingRef={headingRef} answers={answers} onUpdate={update} />
361	          )}
362	          {stage === 2 && (
363	            <StyleStage
364	              headingRef={headingRef}
365	              answers={answers}
366	              onUpdate={update}
367	              logoError={logoError}
368	              onLogoError={setLogoError}
369	            />
370	          )}
371	          {stage === 3 && (
372	            <FeaturesStage
373	              headingRef={headingRef}
374	              selected={answers.featureIds}
375	              onToggle={toggleFeature}
376	            />
377	          )}
378	          {stage === 4 && (
379	            <ReviewStage
380	              headingRef={headingRef}
381	              promptText={promptText}
382	              edited={edited}
383	              onEdit={setEdited}
384	              onRevert={() => setEdited(null)}
385	              basis={{
386	                template:
387	                  (answers.templateId ? getTemplate(answers.templateId) : undefined)?.name ?? null,
388	                look: (answers.lookId ? getLook(answers.lookId) : undefined)?.name ?? null,
389	                features: chosenFeatures.length,
390	                logo: answers.logo?.name ?? null,
391	              }}
392	              caveats={chosenFeatures.flatMap((f) =>
393	                f.caveat != null ? [{ id: f.id, label: f.label, caveat: f.caveat }] : [],
394	              )}
395	              answered={hasInlineAnswers(answers)}
396	            />
397	          )}
398	        </div>
399	      </div>
400	    </Modal>
401	  );
402	}
