433	/** A single-select chip. Real radios, so arrow keys and "3 of 8" come free. */
434	function Chip({
435	  name,
436	  value,
437	  checked,
438	  onSelect,
439	  children,
440	}: {
441	  name: string;
442	  value: string;
443	  checked: boolean;
444	  onSelect: () => void;
445	  children: React.ReactNode;
446	}) {
447	  return (
448	    <label
449	      className={`inline-flex cursor-pointer items-center rounded-full border px-3 py-1.5 text-xs font-medium transition-colors duration-[var(--t-1)] ${WRAPPED_FOCUS} ${
450	        checked
451	          ? "border-brand bg-brand-tint text-brand-ink dark:text-brand"
452	          : "border-hair bg-surface-2 text-ink-2 hover:border-line-mid hover:text-ink"
453	      }`}
454	    >
455	      <input
456	        type="radio"
457	        name={name}
458	        value={value}
459	        checked={checked}
460	        onChange={onSelect}
461	        className="sr-only"
462	      />
463	      {children}
464	    </label>
465	  );
466	}
