18	/**
19	 * Pick a template, answer the handful of questions that template actually
20	 * needs, and leave with a finished prompt.
21	 *
22	 * TWO STAGES, ONE MODAL
23	 * Stage 1 is the gallery: a category filter, a search that reads the prompt
24	 * body as well as the name, and a generated cover per template (see
25	 * ./TemplateCover.tsx — there is no image to use, and nothing in this product
26	 * takes screenshots). Stage 2 is the intake: the per-template questions derived
27	 * from that prompt's own bracketed placeholders (see ./intake.ts), an optional
28	 * logo, an optional palette, and the assembled prompt shown back as an editable
29	 * textarea before anything is committed.
30	 *
31	 * EVERYTHING IN STAGE 2 IS OPTIONAL
32	 * Someone who wants to just start can press the primary button the moment they
33	 * land on stage 2 and get the template's own hand-written prompt, unchanged.
34	 * That is not a degraded path — those 23 prompts already work on their own, and
35	 * an unanswered question simply leaves its bracket in place, which is precisely
36	 * what every one of them instructs the builder to do with a fact it has not
37	 * been told. No field is required, none is validated, and nothing is invented
38	 * to fill a gap.
39	 *
40	 * NOTHING IS LOST GOING BACKWARDS
41	 * Answers, the logo, the palette and any hand-edit of the prompt are held per
42	 * template id for the life of the component, so Back → change your mind →
43	 * forward returns to exactly what was typed. Closing the modal does not clear
44	 * them either; the parent owns `open`, and re-opening resumes.
45	 *
46	 * ACCESSIBILITY
47	 * `Modal` is a native `<dialog>`, so the focus trap, the inert background, the
48	 * top-layer stacking and Escape all come from the platform. What that does NOT
49	 * give is stage changes: the heading (`h2`, owned by Modal) is re-titled per
50	 * stage, each stage's sections are `h3`, and focus is moved explicitly — into
51	 * the intake panel on the way forward, back onto the card you came from on the
52	 * way back — with a `role="status"` line so the change is announced rather than
53	 * only seen.
54	 */
55	
56	export type TemplatePickerResult = {
57	  templateId: string;
58	  /** The finished, editable build prompt with all answers substituted in. */
59	  prompt: string;
60	  /** Data URL, only if the customer uploaded one. */
61	  logoDataUrl?: string;
62	  /** Hex strings the customer chose, in the order they should be applied. */
63	  palette?: string[];
64	};
65	
66	type Stage = "gallery" | "intake";
67	type View = "covers" | "list";
68	type LogoState = { dataUrl: string; name: string; bytes: number; format: "PNG" | "JPEG" };
69	
70	const ALL = "All";
71	const PALETTES: PaletteChoice[] = paletteCatalogue();
72	/** One shared empty object, so an unanswered template does not produce a new
73	    identity on every render and invalidate the assembly memo. */
74	const NO_ANSWERS: Record<string, string> = {};
